<?php
namespace Tests\Feature;
use App\Actions\Approvals\RequestActionApproval;use App\Enums\ApprovalStatus;use App\Enums\ApprovalType;use App\Enums\UserRole;use App\Models\Category;use App\Models\Product;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class NextStaffApprovalsApiTest extends TestCase{use RefreshDatabase;
public function test_separate_owner_can_list_view_and_approve_stock_request():void{$requester=User::factory()->create(['role'=>UserRole::Admin]);$owner=User::factory()->create(['role'=>UserRole::Owner]);$category=Category::create(['name'=>'Approval Next','slug'=>'approval-next','is_active'=>true]);$product=Product::create(['category_id'=>$category->id,'name'=>'Produk Approval Next','slug'=>'produk-approval-next','sku'=>'APR-NEXT','unit'=>'pcs','cost_price'=>100,'selling_price'=>200,'stock'=>2,'minimum_stock'=>1,'is_active'=>true]);$approval=app(RequestActionApproval::class)->handle($requester,ApprovalType::StockAdjustment,$product,['quantity'=>5,'movement_type'=>'purchase','reason'=>'Stok datang'],'Stok datang');Sanctum::actingAs($owner,['staff:approvals']);$this->getJson('/api/v1/staff/approvals?status=pending')->assertOk()->assertJsonPath('data.approvals.0.request_number',$approval->request_number);$this->getJson('/api/v1/staff/approvals/'.$approval->id)->assertOk()->assertJsonPath('data.subject',$product->name)->assertJsonPath('data.permissions.can_decide',true);$this->postJson('/api/v1/staff/approvals/'.$approval->id.'/approve',['notes'=>'Sesuai bukti stok.'])->assertOk();$this->assertSame(7,$product->fresh()->stock);$this->assertSame(ApprovalStatus::Approved,$approval->fresh()->status);}
public function test_requester_cannot_approve_own_request_and_rejection_requires_reason():void{$admin=User::factory()->create(['role'=>UserRole::Admin]);$category=Category::create(['name'=>'Own Approval','slug'=>'own-approval','is_active'=>true]);$product=Product::create(['category_id'=>$category->id,'name'=>'Produk Own','slug'=>'produk-own','sku'=>'OWN-APR','unit'=>'pcs','cost_price'=>100,'selling_price'=>200,'stock'=>2,'minimum_stock'=>1,'is_active'=>true]);$approval=app(RequestActionApproval::class)->handle($admin,ApprovalType::StockAdjustment,$product,['quantity'=>2,'movement_type'=>'purchase','reason'=>'Pengajuan sendiri'],'Pengajuan sendiri');Sanctum::actingAs($admin,['staff:approvals']);$this->postJson('/api/v1/staff/approvals/'.$approval->id.'/approve')->assertUnprocessable()->assertJsonValidationErrors('approval');$this->postJson('/api/v1/staff/approvals/'.$approval->id.'/reject',['notes'=>'x'])->assertUnprocessable()->assertJsonValidationErrors('notes');$this->postJson('/api/v1/staff/approvals/'.$approval->id.'/reject',['notes'=>'Bukti belum lengkap.'])->assertOk();$this->assertSame(ApprovalStatus::Rejected,$approval->fresh()->status);$this->assertSame(2,$product->fresh()->stock);}
public function test_cashier_and_missing_ability_are_rejected():void{$cashier=User::factory()->create(['role'=>UserRole::Cashier]);Sanctum::actingAs($cashier,['staff:approvals']);$this->getJson('/api/v1/staff/approvals')->assertForbidden();$owner=User::factory()->create(['role'=>UserRole::Owner]);Sanctum::actingAs($owner,['staff:dashboard']);$this->getJson('/api/v1/staff/approvals')->assertForbidden();}
}